from prototype import *

def task(n,modes):
    rows={}
    base=None
    for mode in ['base',*modes]:
        frames=OUT/f'{n}.{mode}.quant.dvsi';parms=frames.with_suffix('.parms')
        run(BASE,'parms','--rate','dstar',frames,parms)
        indices=np.array([list(map(int,line.split()[:9])) for line in parms.read_text().splitlines()])
        assert len(indices)*9==frames.stat().st_size
        if base is None:base=indices
        assert np.array_equal(indices[:,:3],base[:,:3]),(n,mode,'pitch/voicing/gain changed')
        rows[mode]={'frames':len(indices),'sha256':hashlib.sha256(frames.read_bytes()).hexdigest(),'changed_frames':int(np.any(indices!=base,axis=1).sum())}
    return n,rows

if __name__=='__main__':
    names={n:['energy_grid','fit_grid','energy_domain_half'] for n in json.loads((OUT/'quant-70.json').read_text())['files']}
    names.update({n:['energy_grid','fit_grid'] for n in json.loads((OUT/'quant-heldout.json').read_text())['files']})
    result={}
    with ProcessPoolExecutor(max_workers=4) as pool:
        for future in as_completed([pool.submit(task,n,m) for n,m in names.items()]):
            n,rows=future.result();result[n]=rows
    (OUT/'audit.json').write_text(json.dumps({'assertions':'Frame counts agree; b0, b1 and b2 identical for every candidate frame. Identity oracle matched baseline frame bytes on every encoding.','files':result},indent=2))
    print(len(result),'recordings checked;',sum(v['base']['frames'] for v in result.values()),'baseline frames; pitch, voicing and gain indices unchanged')

