from prototype import *

def task(n,input_dir,modes):
    reference=read_wav(input_dir/f'{n}.wav');rows={}
    for label in ['base',*modes]:
        model=OUT/f'{n}.{label}.model';oracle=OUT/f'{n}.{label}.oracle'
        lines=[]
        for line in model.read_text().splitlines():
            v=line.split();L=int(v[2]);shape=np.array(list(map(float,v[4:])))
            lines.append(f'0 -1 {shape.mean():.9g} {L} {v[3]} '+' '.join(v[4:])+'\n')
        oracle.write_text(''.join(lines))
        frames=OUT/f'{n}.{label}.quant.dvsi';audio=frames.with_suffix('.wav')
        run(BASE,'encode','--rate','dstar','--no-tone-detect','--oracle-file',oracle,input_dir/f'{n}.wav',frames)
        if label=='base':
            control=OUT/f'{n}.control.dvsi'
            assert frames.read_bytes()==control.read_bytes(),f'identity oracle mismatch: {n}'
        run(BASE,'decode','--rate','dstar',frames,audio)
        rows[label]=score(reference,read_wav(audio),None)
    return n,rows

if __name__=='__main__':
    ap=argparse.ArgumentParser();ap.add_argument('--all',action='store_true');ap.add_argument('--modes',nargs='+',default=['energy_grid','fit_grid']);ap.add_argument('--only',nargs='+');ap.add_argument('--out',default='quant-pilot.json');ap.add_argument('--input-dir',type=Path,default=ROOT/'testdata/corpus');ap.add_argument('--manifest',type=Path);a=ap.parse_args()
    names=[r['name'] for r in json.loads(a.manifest.read_text())['files']] if a.manifest else a.only or (sorted(p.stem for p in a.input_dir.glob('*.wav') if not p.stem.startswith('syn_')) if a.all else PILOT)
    result={'files':{},'summary':{}}
    with ProcessPoolExecutor(max_workers=4) as pool:
        for job in as_completed([pool.submit(task,n,a.input_dir,a.modes) for n in names]):
            n,row=job.result();result['files'][n]=row
            print(n,{m:round(row[m]['pesq']-row['base']['pesq'],3) for m in a.modes},flush=True)
            result['summary']={m:summarise({n:{'baseline':{'score':r['base']},'candidate':{'score':r[m]}} for n,r in result['files'].items()},'score') for m in a.modes}
            (OUT/a.out).write_text(json.dumps(result,indent=2))
    print(json.dumps(result['summary'],indent=2))

