    html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>D-STAR amplitude analysis</title><style>body{max-width:850px;margin:40px auto;padding:0 20px;font:17px system-ui;background:#f5f7fa;color:#17212d}section{background:white;padding:20px;margin:20px 0;border:1px solid #d5dbe3;border-radius:12px}label{display:block;margin:12px 0}audio{display:block;width:100%;margin-top:5px}input,select,button{font:inherit;padding:8px}input{width:90%}</style><h1>D-STAR amplitude analysis</h1><p>Five blind, level-matched pairs. Both encoders are decoded by the AMBE-3000R. The source is the original speech. A and B are randomised independently.</p><p>The selection includes objective improvements and regressions. Listen for consonant clarity, vowel timbre, roughness and hiss. Ratings stay in this browser; download them to share your verdict.</p>'''+''.join(cards)+'''<button id="save">Download ratings</button><script>for(const e of document.querySelectorAll('select,input')){try{e.value=localStorage.getItem('dstar-analysis-20260922-'+e.id)||e.value}catch{}e.addEventListener('change',()=>{try{localStorage.setItem('dstar-analysis-20260922-'+e.id,e.value)}catch{}})}document.getElementById('save').onclick=()=>{const r={};for(const e of document.querySelectorAll('select,input'))r[e.id]=e.value;const a=document.createElement('a');const u=URL.createObjectURL(new Blob([JSON.stringify(r,null,2)],{type:'application/json'}));a.href=u;a.download='dstar-analysis-ratings.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};</script></html>'''
    (listening/'index.html').write_text(html,encoding='utf-8');(listening/'key.json').write_text(json.dumps(key,indent=2))
