#include <mbelib/mbelib.h>
#include "encoder/ambe_quant.hpp"
extern "C" {
#include "mbe_adaptive.h"
#include "ambe_common.h"
}
#include <cmath>
#include <fstream>
#include <sstream>
#include <string>
#include <iostream>

// Diagnostic only: render unquantised lsa (or decoder log2Ml with "decoded").
// Voicing, mixed-excitation gains and synthesis come from the real decoder.
int main(int argc,char** argv) {
    if(argc<3) return 2;
    std::ifstream input(argv[1]);std::ofstream output(argv[2],std::ios::binary);
    if(!input || !output)return 2;
    const bool decoded=argc>3 && std::string(argv[3])=="decoded";
    const auto& tables=mbe::ambe2400Tables();
    mbe_parms cur{},previous{},enhanced{};
    mbe_initMbeParms(&cur,&previous,&enhanced);
    mbe_initAmbeParms_common(&cur,&previous,&enhanced);
    std::string line;
    while(std::getline(input,line)) {
        std::istringstream row(line);int b[9]={};int L;float w0;
        if(!(row>>b[0]>>b[1]>>L>>w0) || L<9 || L>56 || b[0]>=120)return 3;
        b[2]=20;char bits[49]={};
        if(tables.packFields(b,bits)<0 || tables.decodeParms(bits,&cur,&previous)!=0 || cur.L!=L)return 4;
        float sum=0;
        for(int l=1;l<=L;++l) {
            float value;if(!(row>>value) || !std::isfinite(value))return 5;
            // Recover the mixed-excitation level factor from the decoded setup.
            float mixGain=cur.Ml[l]/std::exp2(cur.log2Ml[l]);
            if(!cur.Vl[l])mixGain/=cur.unvcScale;
            cur.log2Ml[l]=decoded?value:value-0.5f*std::log2(static_cast<float>(L));
            cur.Ml[l]=std::exp2(cur.log2Ml[l])*mixGain*(cur.Vl[l]?1.0f:cur.unvcScale);
            sum+=cur.log2Ml[l];
        }
        cur.gamma=sum/static_cast<float>(L)+0.5f*std::log2(static_cast<float>(L));
        mbe_moveMbeParms(&cur,&previous);
        float rm0=mbe_spectralAmpEnhanceWithRm0(&cur);
        float pcm[160];mbe_synthesizeSpeechWithPreEnhRm0f(pcm,&cur,&enhanced,rm0);
        mbe_moveMbeParms(&cur,&enhanced);
        for(float& sample:pcm)sample*=0.125f;
        short samples[160];mbe_floattoshort(pcm,samples);
        output.write(reinterpret_cast<const char*>(samples),sizeof samples);
    }
    return output?0:6;
}
